var tipuesearch = {"pages": [{"title":"About","text":"\n\n\n\n\r\nall: https://cycu.org/all (包羅萬象)\r\nhealth: https://cycu.org/health (健康)\r\nrecipes: https://cycu.org/recipes (食譜)\r\nclothing: https://cycu.org/clothing (衣著)\r\nliving: https://cycu.org/living (住居)\r\ntourism: https://cycu.org/tourism (旅遊)\r\nlearning: https://cycu.org/learning (學習)\r\ntech: https://cycu.org/tech (科技)\r\nart: https://cycu.org/art (藝術)\r\n","tags":"","url":"About.html"},{"title":"Prog","text":"\r\n此頁面的程式需要 static/robot.py 以及 change.py，robot.py 可用於機器人行走模擬，而 change.py 則用來處理易經卦圖的繪製。\r\nrobot.py 模擬所需的圖像取自 reeborg 機器人模擬程式，位於 images/reeborg 目錄中的 images。\r\n導入 robot.py 並指定繪圖區域的範例: robot_ex1.txt，robot_ex2.txt，robot_ex3.txt，robot_ex4.txt。\r\n\r\nversion hello 1 add to 100 機器人巡邏自由行 numpy_ode\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nRun Output 清除輸出區 Reload\r\n\r\n\r\n\r\n\r\n\r\n從 1 累加到 100 part2:\r\n1 add to 100\r\n\r\n\r\nRun Output 清除輸出區 Reload\r\n\r\n\r\n\r\n\r\n\r\n\r\nfunction getUrlParam(key) {\r\n  return new URLSearchParams(window.location.search).get(key);\r\n}\r\nfunction updateUrlParam(key, value) {\r\n  const url = new URL(window.location);\r\n  url.searchParams.set(key, value);\r\n  window.history.replaceState({}, \"\", url);\r\n}\r\nlet pyodide, editor1, editor2;\r\n\r\n/* 兩個編輯器共用一個 Pyodide 與 sys.stdout/stderr，執行工作必須排隊。 */\r\nlet pyodideRunQueue = Promise.resolve();\r\nfunction enqueuePyodideRun(task) {\r\n  const next = pyodideRunQueue.then(task, task);\r\n  pyodideRunQueue = next.catch(() => {});\r\n  return next;\r\n}\r\n\r\ndocument.addEventListener(\"DOMContentLoaded\", async () => {\r\n  try {\r\n    editor1 = ace.edit(\"kw_editor1\");\r\n    editor1.setTheme(\"ace/theme/chrome\");\r\n    editor1.session.setMode(\"ace/mode/python\");\r\n    editor2 = ace.edit(\"kw_editor2\");\r\n    editor2.setTheme(\"ace/theme/chrome\");\r\n    editor2.session.setMode(\"ace/mode/python\");\r\n\r\n    pyodide = await loadPyodide();\r\n    await pyodide.loadPackage([\"numpy\", \"scipy\", \"matplotlib\", \"micropip\"]);\r\n\r\n    // ===== 安全安裝 robot 模組：失敗不中斷整頁 =====\r\n    async function installLocalModule(url, moduleName) {\r\n      try {\r\n        const res = await fetch(url, { cache: \"no-store\" });\r\n        if (!res.ok) {\r\n          console.warn(\"模組載入失敗 (HTTP \" + res.status + \"):\", url);\r\n          return false;\r\n        }\r\n        const code = await res.text();\r\n        if (!code || !code.trim()) {\r\n          console.warn(\"模組內容為空:\", url);\r\n          return false;\r\n        }\r\n        pyodide.FS.writeFile(moduleName + \".py\", code);\r\n        console.log(\"已安裝模組:\", moduleName, \"←\", url);\r\n        return true;\r\n      } catch (e) {\r\n        console.warn(\"模組載入例外:\", url, e);\r\n        return false;\r\n      }\r\n    }\r\n    try {\r\n      const ok =\r\n        (await installLocalModule(\"/static/robot.py\", \"robot\")) ||\r\n        (await installLocalModule(\"/downloads/robot.py\", \"robot\"));\r\n        (await installLocalModule(\"/static/change.py\", \"change\")) ||\r\n        (await installLocalModule(\"/downloads/change.py\", \"change\"));\r\n      if (!ok) console.warn(\"robot 模組未安裝（/static 與 /downloads 都失敗）。其餘功能仍可使用。\");\r\n    } catch (e) {\r\n      console.warn(\"install robot 略過:\", e);\r\n    }\r\n\r\n    const code = `\r\ndef hello():\r\n    print(\"Hello from custom module! (模組定義寫在本網頁中)\")\r\n`;\r\n    pyodide.runPython(code);\r\n\r\n    const GIST_ADD1TO100 =\r\n      \"https://gist.githubusercontent.com/mdecourse/0229a8a017091476a79700b8a190f185/raw/\" +\r\n      \"c48e37714f055c3a0027cbfef59e442a6ef659b9/from_1_add_to_100_1.py\";\r\n    const NUMPY_ODE =\r\n      \"https://gist.githubusercontent.com/mdecycu/ec4bb35dd0769e7a83d2a9fa57878a67/raw/\" +\r\n      \"98d582539545b3c9fbfa35dd3e605c506367618e/pyodide_ode_ex1.py\";\r\n    const PYODIDE_ROBOT_ANIMATION =\r\n      \"https://gist.githubusercontent.com/mdecycu/ec4bb35dd0769e7a83d2a9fa57878a67/raw/\" +\r\n      \"9d164526e5f0fedbdcab913cb8bb180c0cb462a8/pyodide_robot_ex1.py\";\r\n    const FREE_WALK =\r\n      \"https://gist.githubusercontent.com/mdecycu/ec4bb35dd0769e7a83d2a9fa57878a67/raw/\" +\r\n      \"8655bed2bf5c8dfa6e6d776d7b09264f1ed23d47/pyodide_robot_ex3.py\";\r\n\r\n    const src = getUrlParam(\"src\");\r\n    if (src === PYODIDE_ROBOT_ANIMATION) {\r\n      const robotCode = await fetchCode(PYODIDE_ROBOT_ANIMATION);\r\n      editor1.setValue(robotCode, -1);\r\n      updateUrlParam(\"src\", PYODIDE_ROBOT_ANIMATION);\r\n      await runPyodide(editor1, \"kw_console1\", \"brython_div1\");\r\n    } else {\r\n      const initialCode = await fetchCode(src || GIST_ADD1TO100);\r\n      editor1.setValue(initialCode, -1);\r\n      await runPyodide(editor1, \"kw_console1\", \"brython_div1\");\r\n    }\r\n    editor2.setValue(\"\", -1);\r\n\r\n    document.getElementById(\"version\").onclick = () => {\r\n      const vcode = `\r\nimport pyodide\r\nimport sys\r\nimport matplotlib\r\nimport numpy\r\nimport scipy\r\nprint(\"Pyodide version:\", pyodide.__version__)\r\nprint(\"Python version :\", sys.version)\r\nprint(\"matplotlib version:\", matplotlib.__version__)\r\nprint(\"numpy version:\", numpy.__version__)\r\nprint(\"scipy version:\", scipy.__version__)\r\n`;\r\n      editor1.setValue(vcode, -1);\r\n      updateUrlParam(\"src\", \"inline_version\");\r\n      runPyodide(editor1, \"kw_console1\", \"brython_div1\");\r\n    };\r\n    document.getElementById(\"hello_button\").onclick = () => {\r\n      editor1.setValue(\"hello()\", -1);\r\n      updateUrlParam(\"src\", \"inline_hello\");\r\n      runPyodide(editor1, \"kw_console1\", \"brython_div1\");\r\n    };\r\n    document.getElementById(\"add1to100\").onclick = async () => {\r\n      const c = await fetchCode(GIST_ADD1TO100);\r\n      editor1.setValue(c, -1);\r\n      updateUrlParam(\"src\", GIST_ADD1TO100);\r\n      await runPyodide(editor1, \"kw_console1\", \"brython_div1\");\r\n    };\r\n    document.getElementById(\"numpy_ode\").onclick = async () => {\r\n      const c = await fetchCode(NUMPY_ODE);\r\n      editor1.setValue(c, -1);\r\n      updateUrlParam(\"src\", NUMPY_ODE);\r\n      await runPyodide(editor1, \"kw_console1\", \"brython_div1\");\r\n    };\r\n    document.getElementById(\"robot1\").onclick = async () => {\r\n      const rc = await fetchCode(PYODIDE_ROBOT_ANIMATION);\r\n      editor1.setValue(rc, -1);\r\n      updateUrlParam(\"src\", PYODIDE_ROBOT_ANIMATION);\r\n      await runPyodide(editor1, \"kw_console1\", \"brython_div1\");\r\n    };\r\n    document.getElementById(\"free_walk\").onclick = async () => {\r\n      const rc = await fetchCode(FREE_WALK);\r\n      editor1.setValue(rc, -1);\r\n      updateUrlParam(\"src\", FREE_WALK);\r\n      await runPyodide(editor1, \"kw_console1\", \"brython_div1\");\r\n    };\r\n    document.getElementById(\"add1to100part2\").onclick = async () => {\r\n      const c = await fetchCode(GIST_ADD1TO100);\r\n      editor2.setValue(c, -1);\r\n      await runPyodide(editor2, \"kw_console2\", \"brython_div2\");\r\n    };\r\n    document.getElementById(\"kw_run1\").onclick = () =>\r\n      runPyodide(editor1, \"kw_console1\", \"brython_div1\");\r\n    document.getElementById(\"kw_run2\").onclick = () =>\r\n      runPyodide(editor2, \"kw_console2\", \"brython_div2\");\r\n    document.getElementById(\"kw_clear_console1\").onclick = () =>\r\n      clearOutput(\"kw_console1\", \"brython_div1\");\r\n    document.getElementById(\"kw_clear_console2\").onclick = () =>\r\n      clearOutput(\"kw_console2\", \"brython_div2\");\r\n    document.getElementById(\"kw_output1\").onclick = () => {\r\n      const ta = document.getElementById(\"kw_console1\");\r\n      ta.rows = \"15\";\r\n      ta.cols = \"70\";\r\n      ta.scrollTop = 0;\r\n    };\r\n    document.getElementById(\"kw_output2\").onclick = () => {\r\n      const ta = document.getElementById(\"kw_console2\");\r\n      ta.rows = \"15\";\r\n      ta.cols = \"70\";\r\n      ta.scrollTop = 0;\r\n    };\r\n  } catch (e) {\r\n    console.error(\"Pyodide 初始化失敗：\", e);\r\n    const ta = document.getElementById(\"kw_console1\");\r\n    if (ta) ta.value += \"\\n初始化錯誤：\" + (e.message || e.toString());\r\n  }\r\n});\r\n\r\nasync function fetchCode(url) {\r\n  const r = await fetch(url);\r\n  if (!r.ok) throw new Error(\"載入失敗 \" + r.status);\r\n  return await r.text();\r\n}\r\nfunction clearOutput(consoleId, divId) {\r\n  document.getElementById(consoleId).value = \"\";\r\n  document.getElementById(divId).innerHTML = \"\";\r\n}\r\n\r\n/* 把清除、writer 設定、Python 執行、錯誤處理整體放進佇列。 */\r\nasync function runPyodide(editor, consoleId, divId) {\r\n  return enqueuePyodideRun(async () => {\r\n    if (!pyodide) {\r\n      document.getElementById(consoleId).value += \"Pyodide 尚未初始化完成。\\n\";\r\n      return;\r\n    }\r\n    const output = document.getElementById(consoleId);\r\n    const visual = document.getElementById(divId);\r\n    output.value = \"\";\r\n    visual.innerHTML = \"\";\r\n\r\n    await pyodide.runPythonAsync(`\r\nimport sys\r\nclass JsWriter:\r\n  def write(self, s):\r\n    from js import document\r\n    ta = document.getElementById(\"${consoleId}\")\r\n    ta.value += s\r\n    ta.scrollTop = ta.scrollHeight\r\n  def flush(self):\r\n    pass\r\nsys.stdout = JsWriter()\r\nsys.stderr = JsWriter()\r\n`);\r\n    try {\r\n      await pyodide.runPythonAsync(editor.getValue());\r\n    } catch (e) {\r\n      output.value += \"\\n錯誤：\" + (e.message || e.toString());\r\n      output.scrollTop = output.scrollHeight;\r\n    }\r\n  });\r\n}\r\n\r\n\n","tags":"","url":"Prog.html"}]};
